-- Remove matching rows or columns of tiles, then let the remaining tiles fall down.
-- match-grid: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width,height,minimum_run,...tiles]
-- Output: [matched_count,...collapsed_tiles]
-- Tile -1 is empty. Detect horizontal/vertical matches, merge intersections, then apply column
-- gravity. No random refill or cascade.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Replace a number at an existing position in the list.
local function port_put(a,i,v) port_get(a,i); a[i+1]=v end
-- Add one number to the end of the list.
local function port_push(a,v) a[#a+1]=v end

-- 1. Find long enough runs of identical nonempty tiles.
-- 2. Mark each matching tile once, even where a row and column cross.
-- 3. Remove all marked tiles together.
-- 4. Slide surviving tiles to the bottom of each column without changing their order.
local function compute(data)
    local w = 0
    local h = 0
    local minimum_run = 0
    local matched = {}
    local i = 0
    local axis = 0
    local count = 0
    local grid = {}
    local x = 0
    local result = {}
    local lines = 0
    local span = 0
    local line = 0
    local bottom = 0
    local y = 0
    local start = 0
    local cell = 0
    local stride = 0
    local tile = 0
    local end_index = 0
    local j = 0
    w = port_get(data, 0)
    h = port_get(data, 1)
    minimum_run = port_get(data, 2)
    if ((w < 1) or (h < 1) or (minimum_run < 2) or (port_length(data) ~= (3 + (w * h)))) then
        return {-(1)}
    end
    matched = {}
    i = 0
    while (i < (w * h)) do
        port_push(matched, 0)
        i = i + 1
    end
    axis = 0
    while (axis < 2) do
        lines = h
        span = w
        if (axis == 1) then
            lines = w
            span = h
        end
        line = 0
        while (line < lines) do
            start = 0
            while (start < span) do
                cell = ((line * w) + start)
                stride = 1
                if (axis == 1) then
                    cell = ((start * w) + line)
                    stride = w
                end
                tile = port_get(data, (3 + cell))
                end_index = (start + 1)
                while ((end_index < span) and (port_get(data, ((3 + cell) + ((end_index - start) * stride))) == tile)) do
                    end_index = end_index + 1
                end
                if ((tile ~= -(1)) and ((end_index - start) >= minimum_run)) then
                    j = start
                    while (j < end_index) do
                        port_put(matched, (cell + ((j - start) * stride)), 1)
                        j = j + 1
                    end
                end
                start = end_index
            end
            line = line + 1
        end
        axis = axis + 1
    end
    count = 0
    grid = {}
    i = 0
    while (i < (w * h)) do
        count = count + port_get(matched, i)
        port_push(grid, -(1))
        i = i + 1
    end
    x = 0
    while (x < w) do
        bottom = (h - 1)
        y = (h - 1)
        while (y >= 0) do
            cell = ((y * w) + x)
            if ((port_get(matched, cell) == 0) and (port_get(data, (3 + cell)) ~= -(1))) then
                port_put(grid, ((bottom * w) + x), port_get(data, (3 + cell)))
                bottom = bottom - 1
            end
            y = y - 1
        end
        x = x + 1
    end
    result = {count}
    i = 0
    while (i < port_length(grid)) do
        port_push(result, port_get(grid, i))
        i = i + 1
    end
    return result
end
return {compute=compute}
